<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';
import {api,currentAdminAccount} from '../api';import {emptyProduct,productPayload,moneyLabel} from '../catalog-client';import {categoryOptions,safeCmsHtml,type CmsCategory} from '../cms-client';import {mediaError} from '../media-client';import MediaPicker from './MediaPicker.vue';
const role=currentAdminAccount()?.role,canEdit=!!role&&role!=='VIEWER',canArchive=role==='ADMIN'||role==='SUPER_ADMIN';
const rows=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),status=ref(''),category=ref(''),categories=ref<CmsCategory[]>([]),loading=ref(false),busy=ref(false),error=ref(''),categoryError=ref('');
const form=ref<any>(null),saved=ref(''),preview=ref(false),picker=ref(false),target=ref('coverUrl'),newImage=ref('');let generation=0;
const options=computed(()=>categoryOptions(categories.value)),dirty=computed(()=>!!form.value&&JSON.stringify(productPayload(form.value))!==saved.value),pages=computed(()=>Math.max(1,Math.ceil(total.value/20)));
const gallery=computed<string[]>(()=>form.value?.gallery||[]);
defineExpose({hasUnsavedChanges:()=>dirty.value,isBusy:()=>busy.value});
async function mayDiscard(){if(!dirty.value)return true;try{await ElMessageBox.confirm('放弃尚未保存的商品修改？','未保存的修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function load(next=page.value){const request=++generation;page.value=next;loading.value=true;error.value='';try{const {data}=await api.get('/admin/product/page',{params:{page:next,limit:20,sort:'newest',search:search.value||undefined,status:status.value||undefined,categoryId:category.value||undefined}});if(request!==generation)return;rows.value=data.items;total.value=data.total;if(next>pages.value)await load(pages.value)}catch(e){if(request===generation)error.value=mediaError(e)}finally{if(request===generation)loading.value=false}}
async function loadCategories(){try{categories.value=(await api.get('/admin/category',{params:{scope:'PRODUCT'}})).data;categoryError.value=''}catch(e){categoryError.value=mediaError(e)}}
async function edit(id?:string){if(busy.value||!await mayDiscard())return;busy.value=true;try{form.value=id?(await api.get(`/admin/product/${id}`)).data:emptyProduct();saved.value=JSON.stringify(productPayload(form.value));preview.value=false;newImage.value=''}catch(e){ElMessage.error(mediaError(e))}finally{busy.value=false}}
async function close(){if(!busy.value&&await mayDiscard())form.value=null}
async function save(){if(!canEdit||busy.value)return;busy.value=true;try{const result=form.value.id?await api.patch(`/admin/product/${form.value.id}`,productPayload(form.value)):await api.post('/admin/product',productPayload(form.value));form.value=result.data;saved.value=JSON.stringify(productPayload(form.value));await load();ElMessage.success('商品草稿已保存；线上资料及库存未被覆盖')}catch(e){ElMessage.error(mediaError(e))}finally{busy.value=false}}
async function action(kind:string,next?:string){if(!form.value?.id||busy.value||!canEdit||dirty.value)return;try{if(kind==='publish'||next==='ARCHIVED')await ElMessageBox.confirm(kind==='publish'?'确认发布商品资料、价格、库存、销量及外部购买链接？':'归档后公开商品与购物车购买入口失效，资料保留。','确认商品操作',{confirmButtonText:'确认',cancelButtonText:'取消'});busy.value=true;const {data}=await api.post(`/admin/product/${form.value.id}/${kind}`,{baseRevision:form.value.revision,...(next?{status:next}:{})});form.value=data;saved.value=JSON.stringify(productPayload(data));await load();ElMessage.success('操作成功')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(mediaError(e))}finally{busy.value=false}}
function pick(url:string){if(!canEdit||!form.value)return;if(target.value==='gallery'){if(form.value.gallery.length>=30){ElMessage.warning('相册最多 30 张');return}if(!form.value.gallery.includes(url))form.value.gallery.push(url)}else form.value[target.value]=url}
function openPicker(value:string){target.value=value;picker.value=true}
function addImage(){target.value='gallery';if(newImage.value.trim())pick(newImage.value.trim());newImage.value=''}
function moveImage(index:number,offset:number){const images=form.value.gallery;if(index+offset<0||index+offset>=images.length)return;[images[index],images[index+offset]]=[images[index+offset],images[index]]}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{void Promise.all([load(),loadCategories()]);window.addEventListener('beforeunload',beforeUnload)});onUnmounted(()=>{generation++;window.removeEventListener('beforeunload',beforeUnload)});
</script>
<template><section class="cms-manager product-manager"><header class="cms-heading"><div><h1>独立商品库</h1><p>仅管理非流量商品；不创建订单、不处理支付、不自动扣库存或增加销量。</p></div><button v-if="canEdit" :disabled="busy" @click="edit()">＋ 新建商品</button></header><form class="cms-filters" @submit.prevent="load(1)"><input v-model="search" aria-label="搜索商品" maxlength="100" placeholder="商品名称、摘要或 SKU"><select v-model="status" aria-label="商品状态"><option value="">全部状态</option><option>DRAFT</option><option>PUBLISHED</option><option>OFFLINE</option><option>ARCHIVED</option></select><select v-model="category" aria-label="商品分类筛选"><option value="">全部商品分类</option><option v-for="node in options" :key="node.id" :value="node.id">{{'—'.repeat(Math.min(12,node.depth))}} {{node.name}}</option></select><button>搜索商品</button></form><p v-if="categoryError" role="alert">{{categoryError}} <button @click="loadCategories">重试分类</button></p><p v-if="loading" role="status">正在加载商品…</p><p v-else-if="error" role="alert">{{error}} <button @click="load()">重试</button></p><div v-else class="cms-list"><article v-for="item in rows" :key="item.id"><div><strong>{{item.name}}</strong><small>{{moneyLabel(item.price,item.currency)}} · 库存 {{item.stock}} · 销量 {{item.sales}} · {{item.status}} · 版本 {{item.revision}}</small></div><button :disabled="busy" @click="edit(item.id)">{{canEdit?'编辑商品':'查看商品'}}</button></article><p v-if="!rows.length">暂无商品</p></div><nav aria-label="后台商品分页"><button :disabled="loading||page<=1" @click="load(page-1)">上一页</button> {{page}} / {{pages}} 页 · {{total}} 项 <button :disabled="loading||page>=pages" @click="load(page+1)">下一页</button></nav>
<section v-if="form" class="cms-editor" aria-label="商品编辑区"><header class="cms-heading"><h2>{{form.id?'编辑商品':'新建非流量商品'}}</h2><button :disabled="busy" @click="close">关闭商品编辑</button></header><fieldset :disabled="!canEdit||busy"><div class="cms-form-grid"><label>商品名称<input v-model="form.name" maxlength="200"></label><label>商品标识<input v-model="form.slug" maxlength="160" placeholder="devices/router"></label><label>商品类型<select v-model="form.kind"><option value="ACCOUNT">账号类（非流量）</option><option value="SERVICE">定制服务</option><option value="DEVICE">设备</option><option value="OTHER">其他非流量商品</option></select></label><label>SKU<input v-model="form.sku" maxlength="100"></label><label>商品分类<select v-model="form.categoryId"><option value="">未分类</option><option v-for="node in options" :key="node.id" :value="node.id">{{'—'.repeat(Math.min(12,node.depth))}} {{node.name}}</option></select></label><label>币种<input v-model="form.currency" maxlength="3" placeholder="USD / CNY"></label><label>售价<input v-model="form.price" inputmode="decimal" maxlength="13"></label><label>划线价（可空）<input v-model="form.compareAtPrice" inputmode="decimal" maxlength="13"></label><label>库存<input v-model.number="form.stock" type="number" min="0" max="2147483647" step="1"></label><label>销量<input v-model.number="form.sales" type="number" min="0" max="2147483647" step="1"></label><label class="cms-wide">商品摘要<textarea v-model="form.summary" maxlength="1000"></textarea></label><label class="cms-wide">商品详情（Markdown）<textarea v-model="form.description" maxlength="100000" rows="10"></textarea></label><label class="cms-wide">外部支付 / 发卡链接<input v-model="form.externalUrl" maxlength="2000" placeholder="https://外部站点/商品地址"><small>购买统一新窗口跳转；不附加 APPGOG 身份或交易数据。</small></label><label>商品封面<input v-model="form.coverUrl" maxlength="2000"><button type="button" @click="openPicker('coverUrl')">从媒体库选择商品封面</button></label><label>SEO 分享图<input v-model="form.ogImage" maxlength="2000"><button type="button" @click="openPicker('ogImage')">选择商品分享图</button></label><label>SEO 标题<input v-model="form.seoTitle" maxlength="200"></label><label>SEO 关键词<input v-model="form.seoKeywords" maxlength="500"></label><label class="cms-wide">SEO 描述<textarea v-model="form.seoDescription" maxlength="500"></textarea></label></div><section><h3>商品相册（最多 30 张）</h3><button type="button" @click="openPicker('gallery')">从媒体库添加相册图片</button><label>相册图片地址<input v-model="newImage" maxlength="2000"></label><button type="button" @click="addImage">添加图片地址</button><ol class="product-gallery-editor"><li v-for="(url,index) in gallery" :key="`${index}-${url}`"><img :src="url" :alt="`相册图片 ${index+1}`"><span>{{url}}</span><div><button type="button" :disabled="index===0" :aria-label="`前移图片 ${index+1}`" @click="moveImage(index,-1)">前移</button><button type="button" :disabled="index===form.gallery.length-1" :aria-label="`后移图片 ${index+1}`" @click="moveImage(index,1)">后移</button><button type="button" :aria-label="`移除图片 ${index+1}`" @click="form.gallery.splice(index,1)">移除</button></div></li></ol></section></fieldset><div class="cms-actions"><button @click="preview=!preview">{{preview?'关闭商品预览':'预览商品草稿'}}</button><button v-if="canEdit" :disabled="busy" @click="save">保存商品草稿</button><button v-if="canEdit&&form.id&&form.status!=='ARCHIVED'" :disabled="busy||dirty" @click="action('publish')">发布商品</button><button v-if="canEdit&&form.status==='PUBLISHED'" :disabled="busy||dirty" @click="action('status','OFFLINE')">下架商品</button><button v-if="canArchive&&form.id&&form.status!=='ARCHIVED'" :disabled="busy||dirty" @click="action('status','ARCHIVED')">归档商品</button><button v-if="canArchive&&form.status==='ARCHIVED'" :disabled="busy||dirty" @click="action('status','DRAFT')">恢复商品草稿</button></div><p role="status">{{!form.id?'新商品尚未创建':dirty?'有未保存修改':'草稿已保存'}} · {{form.status||'DRAFT'}}</p><p>价格、库存、销量等修改在发布后才生效；售罄商品保留展示但不显示可购买链接。</p><article v-if="preview" class="cms-preview"><h2>{{form.name}}</h2><p>{{form.summary}}</p><p>{{moneyLabel(form.price,form.currency)}} · 库存 {{form.stock}} · 销量 {{form.sales}}</p><img v-if="form.coverUrl" :src="form.coverUrl" alt="商品封面"><div v-html="safeCmsHtml(form.description,'MARKDOWN')"></div><div class="product-thumbnails"><img v-for="url in form.gallery" :key="url" :src="url" alt="相册图片"></div></article></section><MediaPicker :visible="picker" @close="picker=false" @select="pick" /></section></template>
